function calcularAssinaturaEspiritual(zanpakuto){if(!zanpakuto)return"";const nome=(zanpakuto.nome||"").toLowerCase().trim().replace(/[^a-z0-9]/g,"");const conceito=(zanpakuto.conceitoCentral||zanpakuto.elemento||"").toLowerCase().trim().slice(0,20).replace(/[^a-z0-9]/g,"");const mecanica=(zanpakuto.poder||zanpakuto.habilidadePrincipal||"").toLowerCase().trim().slice(0,30).replace(/[^a-z0-9]/g,"");return`zk-sig-${nome}-${conceito}-${mecanica.slice(0,12)}`;}// 2. CÁLCULO DE NÍVEL DE SIMILARIDADE ENTRE DUAS ZANPAKUTŌS
function calcularIndiceSimilaridade(shikaiA,shikaiB){if(!shikaiA||!shikaiB)return 0;let score=0;const nomeA=(shikaiA.nome||"").toLowerCase().trim();const nomeB=(shikaiB.nome||"").toLowerCase().trim();if(nomeA===nomeB&&nomeA.length>0)score+=60;else if(nomeA.length>3&&nomeB.length>3&&(nomeA.includes(nomeB)||nomeB.includes(nomeA)))score+=35;const concA=(shikaiA.conceitoCentral||shikaiA.elemento||"").toLowerCase();const concB=(shikaiB.conceitoCentral||shikaiB.elemento||"").toLowerCase();if(concA&&concB&&(concA===concB||concA.includes(concB)||concB.includes(concA))){score+=25;}const poderA=(shikaiA.poder||shikaiA.habilidadePrincipal||"").toLowerCase();const poderB=(shikaiB.poder||shikaiB.habilidadePrincipal||"").toLowerCase();const wordsA=new Set(poderA.split(/\s+/).filter(w=>w.length>4));const wordsB=new Set(poderB.split(/\s+/).filter(w=>w.length>4));let intersection=0;for(const w of wordsA){if(wordsB.has(w))intersection++;}const maxWords=Math.max(1,Math.min(wordsA.size,wordsB.size));const matchPct=intersection/maxWords*35;score+=Math.min(35,matchPct);return Math.min(100,Math.round(score));}// Obter assinaturas e nomes já registrados em todas as fichas e catálogo
